import {
  Router,
  type ErrorRequestHandler,
  type Request,
  type Response,
} from 'express';
import { z } from 'zod';
import { SourceSyncModeSchema } from '../../types/source-sync';
import {
  GuidanceSourceCreateSchema,
  GuidanceSourceSchema,
} from '../../types/guidance-source';
import type { DesignProfiles } from '../../services/profiles/DesignProfiles';
import type {
  GuidanceOperation,
  TelemetryService,
} from '../../services/TelemetryService';
import {
  GuidanceError,
  GuidanceUploadSchema,
  GuidanceSelectionSchema,
  GuidanceUploadUpdateSchema,
  guidancePayloadByteLength,
  type GuidanceDocument,
  type GuidanceErrorCode,
} from '../../types/guidance';

export const guidanceErrorStatus: Record<GuidanceErrorCode, number> = {
  guidance_not_found: 404,
  guidance_account_changed: 409,
  guidance_auth_required: 401,
  guidance_asset_invalid: 400,
  guidance_source_unavailable: 422,
  guidance_source_changed: 409,
};
const operations: Record<string, GuidanceOperation['operation']> = {
  'POST /guidance': 'add',
  'PATCH /guidance/:id': 'update',
  'DELETE /guidance/:id': 'remove',
  'POST /guidance/resolutions': 'resolve',
  'GET /guidance/:id/verifier': 'verifier',
  'PUT /guidance/:id/source': 'update',
  'PATCH /guidance/:id/source': 'update',
  'DELETE /guidance/:id/source': 'update',
};

export const callerAccount = (req: Request): string | undefined =>
  z.string().min(1).optional().parse(req.get('X-Rivet-Account-Id'));

const describeDocuments = (
  res: Response,
  documents: GuidanceDocument[],
): void => {
  res.locals.guidanceMetadata = {
    documentCount: documents.length,
    byteCount: guidancePayloadByteLength(
      documents.map(({ id, title, markdown, references }) => ({
        id,
        title,
        markdown,
        ...(references ? { references } : {}),
      })),
    ),
  };
};

export const createGuidanceRoutes = (
  profiles: DesignProfiles,
  telemetry?: TelemetryService,
): Router => {
  const router = Router();
  router.use('/guidance', (req, res, next) => {
    const started = Date.now();
    res.setHeader('Cache-Control', 'private, no-store');
    res.once('finish', () => {
      const operation = operations[`${req.method} ${req.route?.path}`];
      if (!operation) return;
      telemetry?.trackGuidanceOperation({
        operation,
        outcome: res.statusCode < 400 ? 'completed' : 'failed',
        durationMs: Date.now() - started,
        ...res.locals.guidanceMetadata,
      });
    });
    next();
  });
  router.get('/guidance', async (req, res) => {
    res.json({ guidance: await profiles.listGuidance(callerAccount(req)) });
  });
  router.post('/guidance', async (req, res) => {
    const result =
      req.body?.source !== undefined
        ? await profiles.guidanceSync.add(
            GuidanceSourceCreateSchema.parse(req.body),
            callerAccount(req),
          )
        : await profiles.addGuidance(
            GuidanceUploadSchema.parse(req.body),
            callerAccount(req),
          );
    const { guidanceWarning, ...guidance } = result;
    describeDocuments(res, [guidance]);
    res
      .status(201)
      .json({ guidance, ...(guidanceWarning ? { guidanceWarning } : {}) });
  });
  router.post('/guidance/resolutions', async (req, res) => {
    const { accountId, ...input } = z
      .record(z.string(), z.unknown())
      .parse(req.body);
    const selection = GuidanceSelectionSchema.parse(input);
    const headerAccountId = callerAccount(req);
    const bodyAccountId = z.string().min(1).optional().parse(accountId);
    if (headerAccountId && bodyAccountId && headerAccountId !== bodyAccountId)
      throw new GuidanceError(
        'guidance_account_changed',
        'Saved guidance account does not match the caller. Sign in and retry.',
      );
    const resolution = await profiles.resolveGuidance(
      selection,
      headerAccountId ?? bodyAccountId,
    );
    describeDocuments(res, resolution.guidance);
    res.locals.guidanceMetadata.mode = selection.mode;
    res.json(resolution);
  });
  router.get('/guidance/:id/verifier', async (req, res) => {
    const packet = await profiles.prepareGuidanceVerification(
      req.params.id,
      callerAccount(req),
    );
    describeDocuments(res, [packet.source]);
    res.json(packet);
  });
  router.get('/guidance/:id', async (req, res) => {
    res.json({
      guidance: await profiles.getGuidance(req.params.id, callerAccount(req)),
    });
  });
  router.put('/guidance/:id/source', async (req, res) => {
    const { source } = z
      .object({ source: GuidanceSourceSchema })
      .strict()
      .parse(req.body);
    const { guidanceWarning, ...guidance } =
      await profiles.guidanceSync.connect(
        { id: req.params.id, source },
        callerAccount(req),
      );
    describeDocuments(res, [guidance]);
    res.json({ guidance, ...(guidanceWarning ? { guidanceWarning } : {}) });
  });
  router.post('/guidance/:id/refreshes', async (req, res) => {
    z.object({})
      .strict()
      .parse(req.body ?? {});
    res.status(202).json({
      sources: await profiles.requestSourceRefresh(
        { family: 'context', sourceId: req.params.id },
        callerAccount(req),
      ),
    });
  });
  router.patch('/guidance/:id/source', async (req, res) => {
    const { syncMode } = z
      .object({ syncMode: SourceSyncModeSchema })
      .strict()
      .parse(req.body);
    const guidance = await profiles.guidanceSync.setSyncMode(
      { id: req.params.id, syncMode },
      callerAccount(req),
    );
    describeDocuments(res, [guidance]);
    res.json({ guidance });
  });
  router.delete('/guidance/:id/source', async (req, res) => {
    const guidance = await profiles.guidanceSync.disconnect(
      req.params.id,
      callerAccount(req),
    );
    describeDocuments(res, [guidance]);
    res.json({ guidance });
  });
  router.patch('/guidance/:id', async (req, res) => {
    const { guidanceWarning, ...guidance } = await profiles.updateGuidance(
      {
        ...GuidanceUploadUpdateSchema.parse(req.body),
        id: req.params.id,
      },
      callerAccount(req),
    );
    describeDocuments(res, [guidance]);
    res.json({ guidance, ...(guidanceWarning ? { guidanceWarning } : {}) });
  });
  router.delete('/guidance/:id', async (req, res) => {
    await profiles.removeGuidance(req.params.id, callerAccount(req));
    res.json({ removed: true });
  });
  const handleError: ErrorRequestHandler = (
    error: unknown,
    _req,
    res,
    next,
  ) => {
    const errorCode =
      error instanceof GuidanceError ? error.code : 'guidance_unavailable';
    res.locals.guidanceMetadata = {
      errorCode: error instanceof z.ZodError ? 'invalid_guidance' : errorCode,
    };
    if (!(error instanceof GuidanceError)) {
      next(error);
      return;
    }
    res
      .status(guidanceErrorStatus[error.code])
      .json({ error: error.message, code: error.code });
  };
  router.use(handleError);
  return router;
};
